/* ============================================================
   11. GRÁFICOS
   ============================================================ */
function tally(arr, fn){
  var m = {};
  arr.forEach(function(d){ var k = fn(d); if(k) m[k] = (m[k] || 0) + 1; });
  return Object.keys(m).map(function(k){ return {k:k, v:m[k]}; }).sort(function(a, b){ return b.v - a.v; });
}
function miniRing(pct, color, size){
  var s = size || 42, t = 5, r = (s - t) / 2, c = s / 2, circ = 2 * Math.PI * r;
  var len = circ * Math.max(0, Math.min(1, pct || 0));
  return '<svg class="ring" viewBox="0 0 ' + s + ' ' + s + '" style="width:' + s + 'px;height:' + s + 'px;flex-shrink:0">'
    + '<circle cx="' + c + '" cy="' + c + '" r="' + r + '" fill="none" stroke="var(--fill)" stroke-width="' + t + '"/>'
    + '<circle cx="' + c + '" cy="' + c + '" r="' + r + '" fill="none" stroke="' + color + '" stroke-width="' + t + '" stroke-linecap="round"'
    + ' stroke-dasharray="' + len.toFixed(2) + ' ' + (circ - len).toFixed(2) + '" transform="rotate(-90 ' + c + ' ' + c + ')"/>'
    + '<text x="' + c + '" y="' + (c + 4) + '" text-anchor="middle" style="font-size:11px;font-weight:600;fill:var(--txt)">'
    + Math.round((pct || 0) * 100) + '%</text></svg>';
}
function donut(data, size, thick){
  var total = data.reduce(function(a, b){ return a + b.v; }, 0) || 1;
  var s = size || 150, t = thick || 22, r = (s - t) / 2, c = s / 2, circ = 2 * Math.PI * r, off = 0;
  var out = '<svg class="chart" viewBox="0 0 ' + s + ' ' + s + '" style="width:' + s + 'px;height:' + s + 'px;flex-shrink:0">';
  out += '<circle cx="' + c + '" cy="' + c + '" r="' + r + '" fill="none" stroke="var(--fill)" stroke-width="' + t + '"/>';
  data.forEach(function(d){
    var len = d.v / total * circ;
    out += '<circle cx="' + c + '" cy="' + c + '" r="' + r + '" fill="none" stroke="' + d.c + '" stroke-width="' + t
      + '" stroke-dasharray="' + len.toFixed(2) + ' ' + (circ - len).toFixed(2) + '" stroke-dashoffset="' + (-off).toFixed(2)
      + '" transform="rotate(-90 ' + c + ' ' + c + ')"><title>' + esc(d.k) + ': ' + d.v + '</title></circle>';
    off += len;
  });
  out += '<text x="' + c + '" y="' + (c - 3) + '" text-anchor="middle" style="font-size:25px;font-weight:600;fill:var(--txt);letter-spacing:-.03em">' + total + '</text>';
  out += '<text x="' + c + '" y="' + (c + 15) + '" text-anchor="middle" style="font-size:11px;fill:var(--txt3)">discos</text>';
  return out + '</svg>';
}
function columns(data, color){
  if(!data.length) return '<div class="tl-empty">Sin datos</div>';
  var W = 640, H = 190, pad = 26, bw = (W - pad * 2) / data.length;
  var max = Math.max.apply(null, data.map(function(d){ return d.v; })) || 1;
  var out = '<svg class="chart" viewBox="0 0 ' + W + ' ' + (H + 34) + '">';
  out += '<line class="axis" x1="' + pad + '" y1="' + H + '" x2="' + (W - pad) + '" y2="' + H + '"/>';
  data.forEach(function(d, i){
    var h = Math.max(3, d.v / max * (H - 26));
    var x = pad + i * bw + bw * .16, w = bw * .68, y = H - h;
    out += '<g><rect class="b" x="' + x.toFixed(1) + '" y="' + y.toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + h.toFixed(1)
      + '" rx="4" fill="' + (color || 'var(--blue)') + '"><title>' + esc(d.k) + ': ' + d.v + '</title></rect>'
      + '<text x="' + (x + w / 2).toFixed(1) + '" y="' + (y - 6).toFixed(1) + '" text-anchor="middle" style="font-size:10.5px;font-weight:600">' + d.v + '</text>'
      + '<text x="' + (x + w / 2).toFixed(1) + '" y="' + (H + 17) + '" text-anchor="middle">' + esc(d.k) + '</text></g>';
  });
  return out + '</svg>';
}
function hbars(data, colorFn, clickable){
  if(!data.length) return '<div class="tl-empty">Sin datos</div>';
  var max = Math.max.apply(null, data.map(function(d){ return d.v; })) || 1;
  return '<div class="hbars">' + data.map(function(d, i){
    return '<div class="hb' + (clickable ? ' click' : '') + '" data-k="' + esc(d.k) + '">'
      + '<div class="top"><span class="n">' + esc(d.k) + '</span><span class="v">' + d.v + '</span></div>'
      + '<div class="track"><span style="width:' + (d.v / max * 100).toFixed(1) + '%;background:'
      + (colorFn ? colorFn(i) : PAL[i % PAL.length]) + '"></span></div></div>';
  }).join('') + '</div>';
}
function areaLine(data, color){
  if(data.length < 2) return '<div class="tl-empty">Sin datos suficientes</div>';
  var W = 640, H = 170, pad = 30;
  var max = Math.max.apply(null, data.map(function(d){ return d.v; })) || 1;
  var stepX = (W - pad * 2) / (data.length - 1);
  var pts = data.map(function(d, i){ return [pad + i * stepX, H - (d.v / max) * (H - 30)]; });
  var path = pts.map(function(p, i){ return (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1); }).join(' ');
  var area = path + ' L' + pts[pts.length - 1][0].toFixed(1) + ' ' + H + ' L' + pts[0][0].toFixed(1) + ' ' + H + ' Z';
  var c = color || 'var(--purple)';
  var out = '<svg class="chart" viewBox="0 0 ' + W + ' ' + (H + 26) + '">';
  out += '<line class="axis" x1="' + pad + '" y1="' + H + '" x2="' + (W - pad) + '" y2="' + H + '"/>';
  out += '<path d="' + area + '" fill="' + c + '" opacity=".14"/>';
  out += '<path d="' + path + '" fill="none" stroke="' + c + '" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>';
  data.forEach(function(d, i){
    out += '<circle cx="' + pts[i][0].toFixed(1) + '" cy="' + pts[i][1].toFixed(1) + '" r="3.2" fill="' + c + '"><title>' + esc(d.k) + ': ' + d.v + '</title></circle>';
    if(data.length <= 14 || i % Math.ceil(data.length / 12) === 0)
      out += '<text x="' + pts[i][0].toFixed(1) + '" y="' + (H + 16) + '" text-anchor="middle">' + esc(d.k) + '</text>';
  });
  return out + '</svg>';
}
