/* Mapa de países: se pinta cada país según su valor, no burbujas sueltas */
function mapaMundo(data, opciones){
  opciones = opciones || {};
  var W = 1000, H = 500;
  var valores = {}, max = 0;
  data.forEach(function(d){
    valores[d.k] = d.v;
    if(d.v > max) max = d.v;
  });
  max = max || 1;
  var base = opciones.color || '#0071e3';
  var claro = opciones.claro || '#c6e0f6';
  var out = '<svg class="chart mapa" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="xMidYMid meet">';
  out += '<rect x="0" y="0" width="' + W + '" height="' + H + '" rx="14" class="mar"/>';
  Object.keys(MUNDO).forEach(function(iso){
    var v = valores[iso] || 0;
    var t = v ? Math.pow(v / max, 0.55) : 0;
    out += '<path class="pais' + (v ? ' con' : '') + '" d="' + MUNDO[iso] + '"'
      + (v ? ' data-pais="' + iso + '" fill="color-mix(in srgb,' + base + ' ' + Math.round(18 + t * 82)
        + '%, ' + claro + ')"' : '')
      + '>' + (v ? '<title>' + esc(nombrePais(iso)) + ': ' + v + (opciones.unidad || '') + '</title>' : '') + '</path>';
  });

  /* etiqueta con la cifra sobre cada país, apartándose si choca */
  var puestas = [];
  data.filter(function(d){ return PAISES[d.k] && MUNDO[d.k]; })
    .sort(function(a, b){ return b.v - a.v; })
    .slice(0, 16)
    .forEach(function(d){
      var p = PAISES[d.k];
      var cx = (p[2] + 180) / 360 * W, cy = (90 - p[1]) / 180 * H;
      var txt = String(d.v) + (opciones.unidad || '');
      var ancho = txt.length * 7.5 + 14, alto = 20;
      var cand = [[cx, cy], [cx, cy - 24], [cx, cy + 24], [cx - 30, cy], [cx + 30, cy],
                  [cx - 46, cy - 20], [cx + 46, cy - 20], [cx, cy - 42], [cx, cy + 42]];
      var el = null;
      for(var i = 0; i < cand.length && !el; i++){
        var x = cand[i][0], y = cand[i][1];
        if(x - ancho / 2 < 4 || x + ancho / 2 > W - 4 || y < 14 || y > H - 10) continue;
        var choca = puestas.some(function(q){
          return Math.abs(q.x - x) < (q.w + ancho) / 2 + 4 && Math.abs(q.y - y) < alto + 2;
        });
        if(!choca) el = cand[i];
      }
      if(!el) return;
      puestas.push({x:el[0], y:el[1], w:ancho});
      var lejos = Math.abs(el[0] - cx) > 6 || Math.abs(el[1] - cy) > 6;
      if(lejos){
        out += '<line class="mapline" x1="' + cx.toFixed(1) + '" y1="' + cy.toFixed(1)
          + '" x2="' + el[0].toFixed(1) + '" y2="' + el[1].toFixed(1) + '"/>';
      }
      out += '<g class="chip" data-pais="' + d.k + '">'
        + '<rect x="' + (el[0] - ancho / 2).toFixed(1) + '" y="' + (el[1] - 10).toFixed(1)
        + '" width="' + ancho.toFixed(1) + '" height="20" rx="10"/>'
        + '<text x="' + el[0].toFixed(1) + '" y="' + (el[1] + 4.5).toFixed(1) + '" text-anchor="middle">'
        + esc(txt) + '</text>'
        + '<title>' + esc(nombrePais(d.k)) + '</title></g>';
    });
  /* leyenda de la escala */
  var lx = 18, ly = H - 26;
  out += '<g class="leyenda"><text x="' + lx + '" y="' + (ly + 12) + '">menos</text>';
  for(var i = 0; i < 5; i++){
    out += '<rect x="' + (lx + 44 + i * 17) + '" y="' + ly + '" width="15" height="12" rx="2.5" fill="color-mix(in srgb,'
      + base + ' ' + Math.round(18 + (i / 4) * 82) + '%, ' + claro + ')"/>';
  }
  out += '<text x="' + (lx + 137) + '" y="' + (ly + 12) + '">más</text></g>';
  return out + '</svg>';
}
/* Un vinilo asoma por la esquina inferior derecha de cada tarjeta */
var SURCOS_SVG = (function(){
  var s = '<svg class="surcos" viewBox="0 0 170 170" aria-hidden="true">';
  for(var r = 18; r < 186; r += 8){
    s += '<circle cx="156" cy="162" r="' + r + '" stroke-opacity="'
      + (((r / 8) % 2) ? '.17' : '.09') + '" stroke-width="1.5"/>';
  }
  s += '<circle cx="156" cy="162" r="15" fill="#fff" fill-opacity=".2" stroke="none"/>'
    + '<circle cx="156" cy="162" r="3.6" fill="#fff" fill-opacity=".38" stroke="none"/></svg>';
  return s;
})();
var BRILLO_SVG = '<svg class="brillo" viewBox="0 0 100 150" aria-hidden="true">'
  + '<path d="M10 118 L58 6" stroke="#fff" stroke-opacity=".2" stroke-width="15" stroke-linecap="round" fill="none"/></svg>';
function wcard(icon, k, v, s, grad){
  return '<div class="wcard" style="background:' + grad + '">' + SURCOS_SVG + BRILLO_SVG
    + '<div class="k">' + esc(k) + '</div><div class="v">' + esc(v) + '</div>'
    + (s ? '<div class="s">' + esc(s) + '</div>' : '') + '</div>';
}

/* ============================================================
   12. ESTADÍSTICAS
   ============================================================ */
var mapaTipo = 'ed', mapaDecada = 0;
var DECADAS = [0, 1960, 1970, 1980, 1990, 2000, 2010, 2020];
var natCache = {};

function datosMapa(tipo, decada){
  var ds = coleccion().filter(function(d){
    if(!decada) return true;
    var y = parseInt(d['año']);
    return y >= decada && y < decada + 10;
  });
  var m = {}, unidad = '', color = '#0071e3', claro = '#cfe3f7', sub = '';
  if(tipo === 'ar'){
    sub = 'De dónde son los artistas que escuchas';
    color = '#af52de'; claro = '#ead9f7';
    ds.forEach(function(d){
      var cc = natCache[plain(d.artista)] || d.paisArtista || '';
      if(cc) m[cc] = (m[cc] || 0) + 1;
    });
  }else if(tipo === 'es'){
    sub = 'Qué países suenan más en tu casa';
    color = '#34c759'; claro = '#d5f2df';
    ds.forEach(function(d){
      if(!d.pais) return;
      var n = (d.escuchasFechas || []).length;
      if(n) m[d.pais] = (m[d.pais] || 0) + n;
    });
    unidad = '';
  }else if(tipo === 'va'){
    sub = 'Dónde está el valor de tu colección';
    color = '#ff9500'; claro = '#fbe6c8';
    unidad = '€';
    ds.forEach(function(d){
      if(!d.pais || !d.tecnica || !d.tecnica.valor) return;
      m[d.pais] = Math.round((m[d.pais] || 0) + d.tecnica.valor);
    });
  }else{
    sub = 'De dónde viene cada prensado';
    ds.forEach(function(d){ if(d.pais) m[d.pais] = (m[d.pais] || 0) + 1; });
  }
  var lista = Object.keys(m).map(function(k){ return {k:k, v:m[k]}; })
    .filter(function(x){ return x.v > 0; })
    .sort(function(a, b){ return b.v - a.v; });
  return {lista:lista, unidad:unidad, color:color, claro:claro, sub:sub};
}
function pintarMapa(){
  var caja = document.getElementById('mapaCaja');
  if(!caja) return;
  var dec = DECADAS[mapaDecada] || 0;
  var r = datosMapa(mapaTipo, dec);
  var sub = document.getElementById('mapSub');
  if(sub) sub.textContent = r.sub + (dec ? ' · años ' + dec : '');
  var lab = document.getElementById('mapDecL');
  if(lab) lab.textContent = dec ? dec + 's' : 'Toda la colección';
  if(!r.lista.length){
    caja.innerHTML = '<div class="tl-empty">'
      + (mapaTipo === 'ar' ? 'Aún no sé de dónde son tus artistas. Pulsa para averiguarlo.'
        : mapaTipo === 'es' ? 'Todavía no hay escuchas registradas en este periodo.'
        : mapaTipo === 'va' ? 'Sin precios consultados todavía.'
        : 'Sin países registrados en este periodo.') + '</div>'
      + (mapaTipo === 'ar' ? '<div style="text-align:center;margin-top:12px">'
        + '<button type="button" class="btn pri sm" id="buscarNat">' + I.globe + 'Averiguar nacionalidades</button></div>' : '');
    var bn = caja.querySelector('#buscarNat');
    if(bn) bn.onclick = buscarNacionalidades;
    return;
  }
  caja.innerHTML = mapaMundo(r.lista, {unidad:r.unidad, color:r.color, claro:r.claro});
  caja.querySelectorAll('[data-pais]').forEach(function(el){
    el.onclick = function(){ verPais(el.dataset.pais); };
  });
}
/* Nacionalidad de cada artista, una sola vez y en segundo plano */
async function buscarNacionalidades(){
  var arts = [];
  coleccion().forEach(function(d){
    var k = plain(d.artista);
    if(k && !d.paisArtista && !natCache[k] && arts.indexOf(d.artista) < 0) arts.push(d.artista);
  });
  if(!arts.length){ pintarMapa(); return; }
  cancelBulk = false;
  bulk = {done:0, total:arts.length, ok:0, actual:''};
  paintBanner();
  for(var i = 0; i < arts.length; i++){
    if(cancelBulk) break;
    bulk.actual = arts[i];
    paintBanner();
    try{
      var j = await mbGet('artist?query=' + encodeURIComponent('artist:"' + lucene(arts[i]) + '"') + '&limit=1');
      var a = (j.artists || [])[0];
      var cc = a && (a.country || (a.area && a.area['iso-3166-1-codes'] && a.area['iso-3166-1-codes'][0])) || '';
      if(cc){
        natCache[plain(arts[i])] = cc;
        DB.discos.forEach(function(d){ if(plain(d.artista) === plain(arts[i])) d.paisArtista = cc; });
        bulk.ok++;
      }
    }catch(e){}
    bulk.done++;
    paintBanner();
  }
  bulk = null;
  persist();
  toast(arts.length + ' artistas consultados');
  setView('stats');
  paintStats();
}

function paintStats(){
  var box = document.getElementById('statsBody');
  if(!box) return;
  var ds = coleccion();
  if(!ds.length){ box.innerHTML = '<div class="blank">' + I.music + '<h3>Sin datos</h3><p>Añade discos para ver tus estadísticas.</p></div>'; return; }

  var nv = ds.filter(function(d){ return d.formato === 'Vinilo'; }).length, nc = ds.length - nv;
  var artistas = tally(ds, function(d){ return d.artista; });
  var generos = tally(ds, function(d){ return d.genero || 'Sin clasificar'; });
  var sellos = tally(ds, function(d){ return d.sello; });
  var paises = tally(ds, function(d){ return d.pais; }).filter(function(p){ return PAISES[p.k]; });
  var decadas = tally(ds, function(d){ var y = parseInt(d['año']); return y ? (Math.floor(y / 10) * 10) + 's' : ''; })
    .sort(function(a, b){ return parseInt(a.k) - parseInt(b.k); });
  var compras = tally(ds, function(d){ return d.fechaCompra ? d.fechaCompra.slice(0, 4) : ''; })
    .sort(function(a, b){ return parseInt(a.k) - parseInt(b.k); });
  var gasto = ds.reduce(function(a, d){ return a + (Number(d.precioCompra) || 0); }, 0);
  var temas = ds.reduce(function(a, d){ return a + d.tracklist.length; }, 0);
  var years = ds.map(function(d){ return parseInt(d['año']); }).filter(function(y){ return y > 1900; });
  var medio = years.length ? Math.round(years.reduce(function(a, b){ return a + b; }, 0) / years.length) : '—';
  var masAntiguo = ds.filter(function(d){ return parseInt(d['año']) > 1900; })
    .sort(function(a, b){ return parseInt(a['año']) - parseInt(b['año']); })[0];
  var masEscuchado = ds.slice().sort(function(a, b){ return (b.escuchas || 0) - (a.escuchas || 0); })[0];
  var decaTop = decadas.slice().sort(function(a, b){ return b.v - a.v; })[0];
  var prestados = ds.filter(function(d){ return d.prestadoA; });

  var porAnio = {}, porMesAct = {}, totalEsc = 0, anioAct = String(new Date().getFullYear());
  ds.forEach(function(d){
    (d.escuchasFechas || []).forEach(function(f){
      var a = String(f).slice(0, 4);
      porAnio[a] = (porAnio[a] || 0) + 1;
      totalEsc++;
      if(a === anioAct){
        var m = String(f).slice(5, 7);
        porMesAct[m] = (porMesAct[m] || 0) + 1;
      }
    });
  });
  var escAnios = Object.keys(porAnio).sort().map(function(a){ return {k:a, v:porAnio[a]}; });
  var MESES = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
  var escMeses = MESES.map(function(nm, i){ var mm = ('0' + (i + 1)).slice(-2); return {k:nm, v:porMesAct[mm] || 0}; });
  var masPuestos = ds.filter(function(d){ return totalEscuchas(d) > 0; })
    .sort(function(a, b){ return totalEscuchas(b) - totalEscuchas(a); }).slice(0, 12);
  var nunca = ds.filter(function(d){ return totalEscuchas(d) === 0; }).length;

  var crec = [], acc = 0, porMes = {};
  ds.forEach(function(d){ var m = (d.fechaAlta || '').slice(0, 7); if(m) porMes[m] = (porMes[m] || 0) + 1; });
  Object.keys(porMes).sort().forEach(function(m){ acc += porMes[m]; crec.push({k:m.slice(2).replace('-', '/'), v:acc}); });

  var valorados = ds.filter(function(d){ return d.valoracion; });
  var notaMedia = valorados.length ? (valorados.reduce(function(a, d){ return a + d.valoracion; }, 0) / valorados.length) : 0;
  var porNota = [5,4,3,2,1].map(function(n){ return {k:n + '★', v: ds.filter(function(d){ return d.valoracion === n; }).length}; });
  var favoritos = ds.filter(function(d){ return d.valoracion >= 4; })
    .sort(function(a, b){ return b.valoracion - a.valoracion || totalEscuchas(b) - totalEscuchas(a); }).slice(0, 12);
  var duraciones = ds.map(function(d){
    var seg = 0;
    d.tracklist.forEach(function(t){ var m = String(t.duracion || '').match(/^(\d+):(\d{2})$/); if(m) seg += (+m[1]) * 60 + (+m[2]); });
    return {d:d, seg:seg};
  }).filter(function(x){ return x.seg > 0; }).sort(function(a, b){ return b.seg - a.seg; });
  var horas = duraciones.reduce(function(a, x){ return a + x.seg; }, 0) / 3600;
  var porLetra = {};
  ds.forEach(function(d){
    var L = (d.artista || '#').replace(/^(el|la|los|las|the|a|an)\s+/i, '').trim()[0];
    L = L ? L.toUpperCase() : '#';
    if(!/[A-Z]/.test(L)) L = '#';
    porLetra[L] = (porLetra[L] || 0) + 1;
  });
  var letras = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ#'.split('').map(function(L){ return {k:L, v:porLetra[L] || 0}; });

  var secc = function(icono, titulo, sub){
    return '<div class="secc"><div class="si">' + icono + '</div><div><h3>' + titulo + '</h3>'
      + (sub ? '<div class="ss">' + sub + '</div>' : '') + '</div></div>';
  };
  box.innerHTML =
    '<div id="efemeride"></div>'
    + '<div id="curiosidad"></div>'
    + '<div id="quiz"></div>'
    + secc(I.vinResumen, 'Resumen')
    + firmaSonora()
    + '<div class="wrapped" style="margin-bottom:18px">'
    + wcard(I.user, 'Artista más repetido', artistas[0] ? artistas[0].k : '—', artistas[0] ? artistas[0].v + ' discos' : '', 'linear-gradient(135deg,#ff2d55,#af52de)')
    + wcard(I.cal, 'Tu década', decaTop ? decaTop.k : '—', decaTop ? decaTop.v + ' discos de esa época' : '', 'linear-gradient(135deg,#0071e3,#30b0c7)')
    + wcard(I.disc, 'El más antiguo', masAntiguo ? masAntiguo['año'] : '—', masAntiguo ? masAntiguo.artista + ' · ' + masAntiguo.titulo : '', 'linear-gradient(135deg,#ff9500,#ffcc00)')
    + wcard(I.music, 'Canciones', temas, 'en ' + ds.length + ' discos', 'linear-gradient(135deg,#34c759,#00c7be)')
    + (masEscuchado && totalEscuchas(masEscuchado) ? wcard(I.playF, 'Más escuchado', masEscuchado.titulo, totalEscuchas(masEscuchado) + ' veces', 'linear-gradient(135deg,#5856d6,#0a84ff)') : '')
    + (totalEsc ? wcard(I.oreja, 'Escuchas registradas', totalEsc, (ds.length - nunca) + ' discos distintos', 'linear-gradient(135deg,#00c7be,#0071e3)') : '')
    + (gasto ? wcard(I.euro, 'Invertido', gasto.toFixed(0) + ' €', 'media de ' + (gasto / ds.length).toFixed(1) + ' € por disco', 'linear-gradient(135deg,#8e8e93,#48484a)') : '')
    + (horas > 1 ? wcard(I.clock, 'Música en casa', Math.round(horas) + ' h', 'seguidas, sin repetir disco', 'linear-gradient(135deg,#ff9500,#ff2d55)') : '')
    + (valorados.length ? wcard(I.estrella, 'Nota media', notaMedia.toFixed(1) + ' ★', valorados.length + ' discos valorados', 'linear-gradient(135deg,#ffb400,#ff7a00)') : '')
    + '</div>'
    + '<div class="kpis">'
    + kpi(I.layers, 'Discos', ds.length, 'var(--blue)')
    + kpi(I.user, 'Artistas', artistas.length, 'var(--pink)')
    + kpi(I.music, 'Géneros', generos.length, 'var(--purple)')
    + kpi(I.globe, 'Países', paises.length, 'var(--teal)')
    + kpi(I.cal, 'Año medio', medio, 'var(--orange)')
    + kpi(I.hand, 'Prestados', prestados.length, 'var(--indigo)')
    + '</div>'
    + secc(I.aguja, 'Escuchas')
    + (totalEsc
      ? '<div class="cards" style="margin-bottom:16px">'
        + '<div class="card full"><h3>Escuchas por año</h3><div class="sub">' + totalEsc
          + ' escuchas registradas · una por disco y día</div><div class="chartwrap">'
          + columns(escAnios, 'var(--green)') + '</div></div>'
        + '<div class="card full"><h3>' + anioAct + ' mes a mes</h3><div class="sub">Cómo va el año en curso</div>'
          + '<div class="chartwrap">' + columns(escMeses, 'var(--teal)') + '</div></div>'
        + '<div class="card"><h3>Calendario</h3><div class="sub">Tu año de escuchas, día a día</div>'
          + '<div id="calMini"></div>'
          + '<button type="button" class="btn pri sm" id="verCal" style="margin-top:14px">' + I.cal + 'Abrir el calendario</button></div>'
        + '<div class="card"><h3>Los que más pones</h3><div class="sub">Pulsa para abrir la ficha</div><div id="topEsc">'
          + '<div class="tl">' + masPuestos.map(function(d){
              return '<div class="trk" data-disco="' + d.id + '" style="cursor:pointer">'
                + '<span class="num">' + totalEscuchas(d) + '</span>'
                + '<span class="nm">' + esc(d.titulo) + '<span style="color:var(--txt3)"> · ' + esc(d.artista) + '</span></span>'
                + '<span class="dur">' + fechaBonita(d.ultimaEscucha) + '</span></div>';
            }).join('') + '</div></div>'
        + tarjetaAguja()
        + tarjetaFavoritas()
        + tarjetaOlvidados()
        + '<div class="card"><h3>Aún sin estrenar</h3><div class="sub">Discos que no has marcado nunca</div>'
          + '<div style="display:flex;align-items:center;gap:16px"><div style="font-size:44px;font-weight:700;letter-spacing:-.04em">'
          + nunca + '</div><div style="font-size:13.5px;color:var(--txt2);line-height:1.45">de ' + ds.length
          + ' discos.<br>' + Math.round((ds.length - nunca) / ds.length * 100) + '% de la colección estrenada.</div></div>'
          + '<button type="button" class="btn sm" id="verNunca" style="margin-top:14px">Ver los que faltan</button></div>'
        + '</div>'
      : '<div class="banner" style="border-left-color:var(--green)"><div><div class="t">Aún no has registrado ninguna escucha</div>'
        + '<div class="s">Pulsa el ▶ de cualquier portada, o «Escuchado hoy» dentro de la ficha, y aquí verás tu año</div></div></div>'
        + '<div class="cards" style="margin-bottom:16px">' + tarjetaOlvidados() + '</div>')
    + secc(I.estanteria, 'Tu colección')
    + '<div class="cards">'
      + '<div class="card"><h3>Soportes</h3><div class="sub">Vinilo frente a CD</div><div class="ringwrap">'
        + donut([{k:'Vinilo', v:nv, c:'#af52de'}, {k:'CD', v:nc, c:'#30b0c7'}], 158, 22)
        + '<div class="legend" style="flex-direction:column;align-items:flex-start;margin:0">'
        + '<div class="lg"><i style="background:#af52de"></i>Vinilo <b>' + nv + '</b> · ' + Math.round(nv / ds.length * 100) + '%</div>'
        + '<div class="lg"><i style="background:#30b0c7"></i>CD <b>' + nc + '</b> · ' + Math.round(nc / ds.length * 100) + '%</div>'
        + '</div></div></div>'
      + '<div class="card"><h3>Géneros</h3><div class="sub">Pulsa para filtrar</div><div class="ringwrap">'
        + donut(generos.slice(0, 9).map(function(g, i){ return {k:g.k, v:g.v, c:PAL[i % PAL.length]}; }), 158, 22)
        + '<div class="legend" id="lgGen" style="flex-direction:column;align-items:flex-start;margin:0;max-height:172px;overflow:auto">'
        + generos.slice(0, 9).map(function(g, i){
            return '<div class="lg" data-gen="' + esc(g.k) + '" style="cursor:pointer"><i style="background:' + PAL[i % PAL.length] + '"></i>'
              + esc(g.k) + ' <b>' + g.v + '</b></div>';
          }).join('')
        + '</div></div></div>'
      + '<div class="card full"><h3>Por década de edición</h3><div class="sub">Cuándo se publicaron tus discos</div><div class="chartwrap">'
        + columns(decadas, 'var(--blue)') + '</div></div>'
      + tarjetaTiempo()
    + '</div>'
    + secc(I.globoSurcos, 'El mundo')
    + '<div class="cards">'
      + '<div class="card full" id="cardMapa"><div class="maphd"><div><h3>El mundo de tu colección</h3>'
        + '<div class="sub" id="mapSub">De dónde viene cada prensado</div></div>'
        + '<div class="seg" id="segMapa">'
          + [['ed','Ediciones'],['ar','Artistas'],['es','Escuchas'],['va','Valor']].map(function(o){
              return '<button type="button" data-m="' + o[0] + '"' + (o[0] === mapaTipo ? ' class="on"' : '') + '>' + o[1] + '</button>';
            }).join('')
        + '</div></div>'
        + '<div class="worldmap" id="mapaCaja"></div>'
        + '<div class="mapdec"><input type="range" id="mapDec" min="0" max="' + (DECADAS.length - 1)
        + '" value="' + mapaDecada + '" step="1"><div class="mapdecl" id="mapDecL"></div></div>'
        + '</div>'
      + '<div class="card"><h3>Top artistas</h3><div class="sub">Pulsa para ver sus discos</div><div id="topArt">'
        + hbars(artistas.slice(0, 12), null, true) + '</div></div>'
      + '<div class="card"><h3>Top sellos</h3><div class="sub">Pulsa para filtrar</div><div id="topSel">'
        + hbars(sellos.slice(0, 12), function(i){ return PAL[(i + 3) % PAL.length]; }, true) + '</div></div>'
      + (crec.length > 2 ? '<div class="card full"><h3>Cómo ha crecido</h3><div class="sub">Discos acumulados desde que llevas la cuenta</div>'
        + '<div class="chartwrap">' + areaLine(crec, 'var(--purple)') + '</div></div>' : '')
      + tarjetaArtistas()
      + tarjetaNacional()
      + tarjetaDuraciones()
      + tarjetaPaleta()
      + tarjetaHuecosSello()
      + (valorados.length > 6 ? '<div class="card"><h3>Cómo puntúas</h3><div class="sub">Reparto de tus estrellas</div>'
        + hbars(porNota, function(i){ return ['#ffb400','#ffc93a','#c8c8cc','#a1a1a6','#c7c7cc'][i]; }) + '</div>' : '')
      + (favoritos.length ? '<div class="card"><h3>Tus favoritos</h3><div class="sub">Cuatro estrellas o más</div><div class="tl">'
        + favoritos.map(function(d){
            return '<div class="trk" data-disco="' + d.id + '" style="cursor:pointer"><span class="nm">' + esc(d.titulo)
              + '<span style="color:var(--txt3)"> · ' + esc(d.artista) + '</span></span>'
              + '<span>' + estrellasHtml(d.valoracion) + '</span></div>';
          }).join('') + '</div></div>' : '')

      + (prestados.length ? '<div class="card"><h3>Prestados ahora</h3><div class="sub">Quién tiene qué</div><div class="tl">'
        + prestados.map(function(d){
            return '<div class="trk"><span class="nm">' + esc(d.titulo) + '</span><span class="dur">' + esc(d.prestadoA) + '</span></div>';
          }).join('') + '</div></div>' : '')
    + '</div>';

  box.querySelectorAll('#topArt .hb').forEach(function(el){
    el.onclick = function(){ fArt = el.dataset.k; grupo = 'none'; document.getElementById('selGroup').value = 'none'; setView('col'); paintCol(); };
  });
  box.querySelectorAll('#topSel .hb').forEach(function(el){
    el.onclick = function(){ fSello = el.dataset.k; setView('col'); paintCol(); };
  });
  box.insertAdjacentHTML('beforeend',
    secc(I.hojaDisco, 'Sacar de la app', 'Catálogo, inventario y valor de la colección')
    + '<div class="dbact">'
      + accion(I.print, 'Catálogo imprimible', 'Con portadas y agrupado por artista, listo para PDF.', 'print', '', 'Generar')
      + accion(I.pin, 'Inventario por ubicación', 'Qué hay en cada estantería o caja.', 'inv', '', 'Generar')
      + accion(I.euro, 'Valor de la colección', 'Lo que valen tus discos según Discogs.', 'valor', '', 'Ver valor')
    + '</div>');
  var onS = function(a, fn){ var el = box.querySelector('[data-a=' + a + ']'); if(el) el.onclick = fn; };
  onS('print', catalogoImprimible);
  onS('inv', inventarioUbicaciones);
  onS('valor', valorColeccion);
  onS('agujaNueva', agujaNueva);
  onS('agujaCfg', agujaAjustes);
  box.querySelectorAll('.paletagrid i').forEach(function(el){
    el.onclick = function(){ openDetail(el.dataset.disco); };
  });
  box.querySelectorAll('.olvt').forEach(function(el){
    el.onclick = function(){ openDetail(el.dataset.disco); };
  });
  pintaEfemeride(box.querySelector('#efemeride'));
  pintaCuriosidad(box.querySelector('#curiosidad'));
  pintaQuiz(box.querySelector('#quiz'));
  pintarMapa();
  box.querySelectorAll('#segMapa button').forEach(function(b){
    b.onclick = function(){
      mapaTipo = b.dataset.m;
      box.querySelectorAll('#segMapa button').forEach(function(x){ x.className = x.dataset.m === mapaTipo ? 'on' : ''; });
      pintarMapa();
    };
  });
  var sl = box.querySelector('#mapDec');
  if(sl) sl.oninput = function(){ mapaDecada = +sl.value; pintarMapa(); };
  box.querySelectorAll('[data-pais]').forEach(function(el){
    el.onclick = function(){ verPais(el.dataset.pais); };
  });
  box.querySelectorAll('[data-disco]').forEach(function(el){
    el.onclick = function(){ openDetail(el.dataset.disco); };
  });
  var vc = box.querySelector('#verCal');
  if(vc) vc.onclick = function(){ calendarioEscuchas('anio'); };
  var mini = box.querySelector('#calMini');
  if(mini){
    var pd = {};
    ds.forEach(function(d){ (d.escuchasFechas || []).forEach(function(f){ if(f.slice(0, 4) === anioAct) pd[f] = (pd[f] || 0) + 1; }); });
    var mx = Math.max.apply(null, Object.keys(pd).map(function(k){ return pd[k]; }).concat([1]));
    var celdas = '';
    var ini = new Date(+anioAct, 0, 1), fin = new Date(+anioAct, 11, 31);
    for(var t = ini.getTime(); t <= fin.getTime(); t += 86400000){
      var f = new Date(t);
      var iso = f.getFullYear() + '-' + ('0' + (f.getMonth() + 1)).slice(-2) + '-' + ('0' + f.getDate()).slice(-2);
      var n = pd[iso] || 0;
      celdas += '<i class="cday n' + (n ? Math.min(4, Math.ceil(n / mx * 4)) : 0) + '"></i>';
    }
    mini.innerHTML = '<div style="display:grid;grid-template-columns:repeat(28,1fr);gap:2px">' + celdas + '</div>';
  }
  var vn = box.querySelector('#verNunca');
  if(vn) vn.onclick = function(){
    fType = 'noesc';
    document.querySelectorAll('#segType button').forEach(function(x){ x.className = x.dataset.f === 'noesc' ? 'on' : ''; });
    setView('col'); paintCol();
  };
  box.querySelectorAll('[data-gen]').forEach(function(el){
    el.onclick = function(){ fGen = el.dataset.gen; setView('col'); paintCol(); };
  });
  var va = box.querySelector('#verAdn');
  if(va) va.onclick = adnMusical;
}

